def reserve_existing_codes(apps, schema_editor):
    Sequence = apps.get_model('inventory', 'CatalogueSequence')
    Reservation = apps.get_model('inventory', 'ConsumableCodeReservation')
    Consumable = apps.get_model('inventory', 'Consumable')
    alias = schema_editor.connection.alias
    Sequence.objects.using(alias).get_or_create(scope='catalogue-lock', defaults={'value': 0})
